import{_ as t,o as n,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"FrequencyTrack","description":"","frontmatter":{"title":"FrequencyTrack","order":8},"headers":[],"relativePath":"mods/freqtrack.md","filePath":"mods/freqtrack.md","lastUpdated":1786957039000}'),o={name:"mods/freqtrack.md"};function s(i,e,l,d,c,g){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="frequencytrack" tabindex="-1">FrequencyTrack <a class="header-anchor" href="#frequencytrack" aria-label="Permalink to &quot;FrequencyTrack&quot;">​</a></h1><p><strong>Frequency Track Laying Tool</strong> — An ADOFAI editor Mod. Automatically lays down tiles on the track based on frequency (pitch), supporting three generation methods: <strong>fixed frequency segments</strong>, <strong>glissando (frequency gradient)</strong>, and <strong>noise segments</strong>, with <strong>auto speed adjustment</strong> so pitch matches BPM precisely (0 error).</p><blockquote><p>Part of the <strong>EditorExtensions</strong> mod (Unity Mod Manager format) in the <code>adofaiex/ADOFAIMods</code> repository. FreqTrack was co-developed by StArray and AI assistance.</p></blockquote><h2 id="installation-enabling" tabindex="-1">Installation &amp; Enabling <a class="header-anchor" href="#installation-enabling" aria-label="Permalink to &quot;Installation &amp; Enabling&quot;">​</a></h2><ol><li>Place the compiled <code>EditorExtensions</code> Mod in ADOFAI&#39;s <code>Mods</code> directory</li><li>Open <strong>Mod Settings</strong> in-game (Unity Mod Manager window)</li><li>Check <strong>Enable FreqTrack</strong></li><li>Optional: switch between <strong>English / Chinese</strong> language; check <strong>Enable FreqTrack Logs</strong> for detailed debug logs (off by default)</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Switching the language refreshes panel text in real time (including font: SourceSans3 for English / Source Han Sans for Chinese).</p></div><h2 id="opening-the-panel" tabindex="-1">Opening the Panel <a class="header-anchor" href="#opening-the-panel" aria-label="Permalink to &quot;Opening the Panel&quot;">​</a></h2><p>In the ADOFAI editor, the FreqTrack panel automatically shows/hides when you <strong>toggle angle input mode</strong> (<code>ToggleAngleInputMode</code>, the &quot;Angle&quot; button in the bottom-left of the editor).</p><p>The panel requires <strong>selecting a starting tile</strong> — generated tiles are inserted after the currently selected tile.</p><h2 id="panel-interface" tabindex="-1">Panel Interface <a class="header-anchor" href="#panel-interface" aria-label="Permalink to &quot;Panel Interface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Description</th></tr></thead><tbody><tr><td>Collapse button <code>▼ / ▶</code></td><td>Expand / collapse panel content</td></tr><tr><td><strong>Outer ring</strong></td><td>When enabled, uses the outer ring (large circle) angle formula for generation — larger circles at higher frequencies</td></tr><tr><td><strong>Beats</strong></td><td>When enabled, the count input is in <strong>beats</strong>; when disabled, in <strong>tiles</strong></td></tr><tr><td><strong>Start pitch</strong></td><td>Equal-tempered pitch dropdown (C0~B8, A4=440Hz) — selecting auto-fills the frequency</td></tr><tr><td><strong>Frequency</strong></td><td>Start frequency (Hz), manually editable</td></tr><tr><td><strong>End pitch</strong></td><td>Glissando end pitch dropdown</td></tr><tr><td><strong>End frequency</strong></td><td>Glissando end frequency (Hz)</td></tr><tr><td><strong>Count</strong></td><td>Beats toggle off = target tile count; on = target beat count</td></tr><tr><td><strong>Insert beat interval</strong></td><td>Insert a &quot;jump marker pair&quot; every N beats (0 = no insertion), rhythm unchanged</td></tr><tr><td><strong>Glissando easing</strong></td><td>Easing function for frequency change during glissando (30 options)</td></tr><tr><td><strong>Apply pitch</strong></td><td>Generate a <strong>fixed frequency</strong> tile segment at the current frequency</td></tr><tr><td><strong>Glissando</strong></td><td><strong>Gradient</strong> from start frequency to end frequency</td></tr><tr><td><strong>Generate noise</strong></td><td>Generate a noise segment with random per-tile offset around the current frequency</td></tr></tbody></table><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="frequency-bpm-and-tiles" tabindex="-1">Frequency, BPM, and Tiles <a class="header-anchor" href="#frequency-bpm-and-tiles" aria-label="Permalink to &quot;Frequency, BPM, and Tiles&quot;">​</a></h3><ul><li><strong>Frequency (Hz) = tiles per second = display BPM ÷ 60</strong>. Example: 120 BPM → 2 tiles/sec → 2Hz</li><li>Beats per tile <code>TileBeats(entry, exit)</code> is determined by the entry/exit angle difference: <code>((180-(exit-entry)) mod 360 + 360) mod 360 / 180</code></li></ul><h3 id="auto-speed-adjustment" tabindex="-1">Auto Speed Adjustment <a class="header-anchor" href="#auto-speed-adjustment" aria-label="Permalink to &quot;Auto Speed Adjustment&quot;">​</a></h3><p>Regardless of the current BPM, the Mod writes a <code>SetSpeed</code> event at the segment start:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>newBpm = hz × 60 × TileBeats(0, segAngle)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This ensures <strong>the pitch heard in-game is exactly equal to the input frequency</strong> (0 error). For outer rings, beats per tile is naturally doubled, so display BPM is consistent between inner and outer rings.</p><h3 id="angle-formula" tabindex="-1">Angle Formula <a class="header-anchor" href="#angle-formula" aria-label="Permalink to &quot;Angle Formula&quot;">​</a></h3><ul><li>Inner ring: <code>segAngle = 180 - 180 × (hzFormBPM × bpmFactor) / hz</code></li><li>Outer ring: <code>segAngle = 180 - 360 × (hzFormBPM × bpmFactor) / hz</code></li><li><code>hzFormBPM</code> = current BPM ÷ 60; <code>bpmFactor</code> = fold multiplier with base 2 (ensures the angle falls within a reasonable range)</li></ul><h3 id="pitch-selector" tabindex="-1">Pitch Selector <a class="header-anchor" href="#pitch-selector" aria-label="Permalink to &quot;Pitch Selector&quot;">​</a></h3><p>Based on <strong>equal temperament</strong>, referencing A4 = 440Hz, range C0 (16.352Hz) ~ B8 (7902.133Hz). Selecting a pitch auto-fills the corresponding frequency, which can also be fine-tuned manually.</p><h2 id="feature-details" tabindex="-1">Feature Details <a class="header-anchor" href="#feature-details" aria-label="Permalink to &quot;Feature Details&quot;">​</a></h2><h3 id="apply-pitch-—-fixed-frequency-segment" tabindex="-1">Apply Pitch — Fixed Frequency Segment <a class="header-anchor" href="#apply-pitch-—-fixed-frequency-segment" aria-label="Permalink to &quot;Apply Pitch — Fixed Frequency Segment&quot;">​</a></h3><ol><li>Select a starting tile</li><li>Choose a <strong>start pitch</strong> or directly enter a <strong>frequency</strong></li><li>Set the <strong>count</strong> (tiles or beats)</li><li>Optional: set <strong>insert beat interval</strong> (must be ≥1 integer)</li><li>Optional: enable <strong>outer ring</strong></li><li>Click <strong>Apply Pitch</strong></li></ol><p>Result: generates a constant-frequency tile segment after the selected tile, with auto speed adjustment — pitch exactly equals the input frequency.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>When frequency ≤ 0 or input is empty, it won&#39;t execute and only shows a prompt (to avoid producing NaN tiles).</p></div><h3 id="glissando-—-frequency-gradient-segment" tabindex="-1">Glissando — Frequency Gradient Segment <a class="header-anchor" href="#glissando-—-frequency-gradient-segment" aria-label="Permalink to &quot;Glissando — Frequency Gradient Segment&quot;">​</a></h3><ol><li>Select a starting tile</li><li>Set <strong>start frequency</strong> and <strong>end frequency</strong> (end pitch / end frequency input)</li><li>Set the <strong>count</strong> (target tiles or beats)</li><li>Choose a <strong>glissando easing</strong> function (default Linear)</li><li>Optional: <strong>insert beat interval</strong>, <strong>outer ring</strong></li><li>Click <strong>Glissando</strong></li></ol><p>Result: tile angles gradient continuously from start frequency to end frequency following the easing curve, creating a smooth glissando effect.</p><ul><li><strong>By beats</strong>: generates up to the target beat count</li><li><strong>By tiles</strong>: generates up to the target tile count</li><li>Speed factor folds at the <strong>lower frequency</strong> of both ends, ensuring pitch matches throughout</li></ul><h3 id="generate-noise" tabindex="-1">Generate Noise <a class="header-anchor" href="#generate-noise" aria-label="Permalink to &quot;Generate Noise&quot;">​</a></h3><ol><li>Select a starting tile</li><li>Set <strong>start frequency</strong> and <strong>count</strong> (tiles or beats)</li><li>Optional: <strong>outer ring</strong></li><li>Click <strong>Generate Noise</strong></li></ol><p>Result: centered on the current frequency&#39;s base angle, <strong>each tile randomly offsets ±25°</strong>, generating a segment that sounds like noise (rhythm / frequency base still matches the input).</p><h3 id="insert-beat-interval-markers" tabindex="-1">Insert Beat Interval Markers <a class="header-anchor" href="#insert-beat-interval-markers" aria-label="Permalink to &quot;Insert Beat Interval Markers&quot;">​</a></h3><p>Inserts a &quot;jump marker pair&quot; every specified number of beats: first jumps to a special angle <code>target</code>, then falls back to a 180° rotated position.</p><ul><li>The marker pair&#39;s total duration <strong>exactly equals</strong> one normal tile (rhythm completely unchanged)</li><li>Commonly used to create &quot;percussion&quot; or marker points in sustained tones / glissandos</li><li>0 means no insertion; inputs &lt; 1 are treated as 1, non-integers are auto-rounded</li></ul><h2 id="glissando-easing-functions-30" tabindex="-1">Glissando Easing Functions (30) <a class="header-anchor" href="#glissando-easing-functions-30" aria-label="Permalink to &quot;Glissando Easing Functions (30)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Functions</th></tr></thead><tbody><tr><td>Linear</td><td>Linear</td></tr><tr><td>Sine</td><td>InSine / OutSine / InOutSine</td></tr><tr><td>Quadratic</td><td>InQuad / OutQuad / InOutQuad</td></tr><tr><td>Cubic</td><td>InCubic / OutCubic / InOutCubic</td></tr><tr><td>Quartic</td><td>InQuart / OutQuart / InOutQuart</td></tr><tr><td>Quintic</td><td>InQuint / OutQuint / InOutQuint</td></tr><tr><td>Exponential</td><td>InExpo / OutExpo / InOutExpo</td></tr><tr><td>Circular</td><td>InCirc / OutCirc / InOutCirc</td></tr><tr><td>Back</td><td>InBack / OutBack / InOutBack</td></tr><tr><td>Elastic</td><td>InElastic / OutElastic / InOutElastic</td></tr><tr><td>Bounce</td><td>InBounce / OutBounce</td></tr></tbody></table><ul><li><strong>In</strong>: slow→fast; <strong>Out</strong>: fast→slow; <strong>InOut</strong>: slow at both ends, fast in the middle</li><li>Easing applies to the <strong>frequency</strong> (Hz) linear interpolation: <code>freq(t) = startHz + (endHz - startHz) × Ease(t)</code></li><li>Choosing elastic / bounce causes the frequency to briefly <strong>exceed the end value</strong> before bouncing back — great for exaggerated glissando effects</li></ul><h2 id="language-settings" tabindex="-1">Language &amp; Settings <a class="header-anchor" href="#language-settings" aria-label="Permalink to &quot;Language &amp; Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td>English / Chinese</td><td>Switch panel language (real-time refresh, including font)</td></tr><tr><td>Enable FreqTrack</td><td>Master toggle — when off, panel is hidden and features are disabled</td></tr><tr><td>Enable QuickOpen / DisableLimit</td><td>Other feature toggles in the same Mod</td></tr><tr><td>Enable FreqTrack Logs</td><td>Output detailed apply/glissando/noise logs, marker timestamps, panel layout (off by default, for debugging)</td></tr></tbody></table><h2 id="tips-common-issues" tabindex="-1">Tips &amp; Common Issues <a class="header-anchor" href="#tips-common-issues" aria-label="Permalink to &quot;Tips &amp; Common Issues&quot;">​</a></h2><ul><li><strong>Pitch inaccurate?</strong> Confirm the frequency input is correct — the Mod auto-adjusts speed (SetSpeed), and in-game display BPM = frequency × 60. Enable logs to see <code>speed: newBpm=..., freq≈...Hz</code> for verification</li><li><strong>Only a few tiles generated?</strong> When count is 0 or empty: apply/noise defaults to 1 tile, glissando to 32 tiles</li><li><strong>Want to create percussion/markers?</strong> Use <strong>insert beat interval</strong> — rhythm stays completely unchanged</li><li><strong>Outer ring vs inner ring?</strong> Outer ring doubles beats per tile — same frequency means fewer outer ring revolutions and larger visuals; pitch is identical</li><li><strong>Glissando not gliding?</strong> Confirm end frequency differs from start; choosing non-linear easing (e.g. elastic/bounce) can enhance the gradient feel</li><li><strong>Panel not appearing?</strong> Toggle the &quot;angle input mode&quot; switch once in the editor, or confirm the Mod master toggle is enabled</li><li><strong>Logs not outputting?</strong> Check &quot;Enable FreqTrack Logs&quot; in Mod settings</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Repository: <a href="https://github.com/adofaiex/ADOFAIMods" target="_blank" rel="noreferrer">adofaiex/ADOFAIMods</a> (EditorExtensions + InformationDisplay)</li><li>Other editor enhancements (CustomRotateAngle / DisableLimit / QuickOpen) are also in this repository, installed together with EditorExtensions</li></ul>',46)])])}const p=t(o,[["render",s]]);export{h as __pageData,p as default};
